shader_translation.glsl:
// Key snippet:
float dist = length(p1 - p2);
float connect = step(dist, 0.02); // threshold
vec3 color = mix(vec3(0), lineColor, connect);

// Key snippet:
float phase = mod(iTime * 10.0 + float(id % 2) * 225.0, 450.0);
float hue = (id % 2 == 0) ? 0.0 : 128.0;

// Key snippet:
float dir = (mod(ring, 2.0) < 0.5) ? 1.0 : -1.0;
float angle = iTime * speed * dir + ringOffset;
// Trail as overlapping circles, not lines
for(float t = 0; t < 10; t++) {
    float trailAngle = angle - t * 0.1 * dir;
    drawCircle(polarToCartesian(trailAngle, radius), 5.0);
}

// Key snippet:
float n = noise3D(centroid * scale);
float visible = step(0.4, n) * (1.0 - step(0.6, n));
// Inset triangle
vec3 inset = mix(centroid, vertex, 0.6);
gl_Position = visible > 0.5 ? projection * vec4(inset, 1) : vec4(0);

// Key snippet:
float angle = iTime * 14.4;
float radius = mod(iTime * 3.0, 360.0);
vec2 spawnPos = vec2(cos(angle), sin(angle)) * radius * 0.01;
// Noise jitter for organic feel
spawnPos += (noise2D(spawnPos + iTime) - 0.5) * 0.002;

// Key snippet:
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
// Seed with frame number
float seededRandom = hash(vec2(float(id), iTime * 60.0));

// Key snippet:
float life = age / maxAge;
float alpha = life < 0.5 ? 1.0 : smoothstep(0.5, 1.0, life);
alpha = 1.0 - alpha; // invert for fade out
gl_FragColor.a *= alpha;

// Key snippet (conceptual - blend modes are GL state):
// ADD mode: glBlendFunc(GL_ONE, GL_ONE)
// Result: src + dest (ethereal glow)

// SUBTRACT mode: glBlendFunc(GL_ZERO, GL_ONE_MINUS_SRC_COLOR)
// Result: dest - src (aggressive cutting)

// In shader, emulate ADD:
vec4 addBlend = src + dest;
// Emulate SUBTRACT:
vec4 subBlend = dest - src;

// Key snippet:
vec3 gridPos = floor(worldPos * gridScale);
float n = noise3D(gridPos * 0.1);
float exists = step(0.5, n);
// Only render if noise > threshold
if (exists > 0.5) {
    renderCube(gridPos / gridScale);
}

// Key snippet (conceptual - requires SSBO or texture):
uniform sampler2D trailBuffer;
// Store position in ring buffer
int idx = int(mod(iFrame, TRAIL_LENGTH));
// Read previous positions for trail
for(int i = 0; i < TRAIL_LENGTH; i++) {
    vec2 trailPos = texelFetch(trailBuffer, ivec2(i, id), 0).xy;
    float fade = 1.0 - float(i) / float(TRAIL_LENGTH);
    drawPoint(trailPos, fade * size);
}

// Key snippet:
vec3 d = fwidth(barycentric);
vec3 edge = smoothstep(vec3(0.0), d * 1.5, barycentric);
float edgeFactor = min(min(edge.x, edge.y), edge.z);
vec3 wireframe = mix(vec3(1.0), solidColor, edgeFactor);

// Not a shader technique - pipeline step
// Typically: save frame buffer each frame, then:
// ffmpeg -framerate 30 -i frame_%04d.png -c:v libx264 output.mp4

// Key snippet:
velocity.y -= gravity * dt;
// Ring-ring collision: check distance between centers
// vs sum of radii, apply impulse
float dist = length(ringA.center - ringB.center);
float overlap = (ringA.radius + ringB.radius) - dist;
if(overlap > 0) {
    vec2 normal = normalize(ringA.center - ringB.center);
    ringA.velocity += normal * overlap * stiffness;
}

// Key snippet:
float heartSDF(vec2 p) {
    p.y = -p.y;
    vec2 q = vec2(p.x, p.y);
    float a = q.x * q.x + q.y * q.y - 0.25;
    return a * a * a - q.x * q.x * q.y * q.y * q.y;
}
// Parametric:
float t = iTime;
vec2 heartPos = vec2(16*pow(sin(t),3), 13*cos(t)-5*cos(2*t)-2*cos(3*t)-cos(4*t)) * 0.01;

// Key snippet:
float z = fract(iTime * speed + objectId * spacing);
float scale = 1.0 / (z + 0.1);
vec2 pos = (worldPos - 0.5) * scale + 0.5;
float alpha = smoothstep(0, 0.1, z) * smoothstep(1.0, 0.9, z);
// Draw sprite at pos with scale and alpha

// Key snippet:
float swell = sin(iTime * frequency + noise3D(position) * 5.0) * 0.5 + 0.5;
vec3 displaced = position + normal * swell * maxDisplacement;
gl_Position = projection * modelView * vec4(displaced, 1.0);

// Key snippet:
bool frameA = fract(iTime * 4.0) < 0.5;
vec3 color = frameA ? renderStateA(uv) : renderStateB(uv);
// States can be completely different
// Creates harsh cut, no interpolation

// Key snippet:
float textSDF(vec2 uv, int letter) {
    // SDF for letter shape
    return distance to letter boundary;
}
// Use text as mask
float inText = step(0, textSDF(uv, letter));
// Or emit particles from text edges
vec2 emitPos = textEdgePosition(letter, random);

// Key snippet:
float p = 2.0 + noise1D(iTime * 0.5) * 3.0;
float q = 3.0 + noise1D(iTime * 0.3 + 100) * 2.0;
float r = cos(q * theta) + 2.0;
vec3 pos = vec3(r * cos(p * theta), r * sin(p * theta), -sin(q * theta));

// Key snippet:
vec3 normal = calculateNormal(position);
// Flip based on noise
float flip = step(0.5, noise3D(position * 2.0));
normal *= mix(1.0, -1.0, flip);
// Or flip entire geometry
gl_FrontFacing = !gl_FrontFacing;
// Emulate in shader:
vec3 viewDir = normalize(cameraPos - position);
float facing = dot(normal, viewDir);
if(facing < 0) normal = -normal;

// Key snippet:
vec2 hexUV = hexGrid(uv * 10.0);
float hexDist = hexSDF(hexUV);
// Deform based on noise
float deform = noise3D(vec3(hexCenter, iTime * 0.1));
vec2 displaced = hexCenter + hexUV * (1.0 + deform * 0.3);
float hex = smoothstep(0.1, 0.0, hexDist);

// Key snippet:
// For each circle
for(int i = 0; i < circleCount; i++) {
    float d = length(uv - circles[i].center);
    // Grow until hitting neighbor
    circles[i].radius += growthRate;
    // Check collision with all other circles
    for(int j = 0; j < circleCount; j++) {
        if(i == j) continue;
        float minDist = circles[i].radius + circles[j].radius;
        float actualDist = length(circles[i].center - circles[j].center);
        if(actualDist < minDist) {
            circles[i].radius = actualDist - circles[j].radius;
        }
    }
}

// Key snippet:
vec2 tileId = floor(uv * tileCount);
vec2 tileUV = fract(uv * tileCount);
// Scattered position based on tileId hash
vec2 scatter = hash2(tileId) * 2.0 - 1.0;
// Assembly progress
float assemble = smoothstep(0, 1, iTime * 0.1);
vec2 finalPos = mix(scatter, tileId / tileCount, assemble);
// Rotation during assembly
float rotation = (1.0 - assemble) * PI * hash1(tileId);

// Key snippet:
// For each arrow at grid position
vec2 toTarget = target - arrowPos;
float targetAngle = atan(toTarget.y, toTarget.x);
// Smooth rotation
float angle = mix(arrowAngle, targetAngle, rotationSpeed);
// Multiple targets
for(int t = 0; t < targetCount; t++) {
    float weight = 1.0 / length(targets[t] - arrowPos);
    targetAngle += atan(targets[t].y - arrowPos.y, targets[t].x - arrowPos.x) * weight;
}

// Key snippet:
// Ribbon defined by curve + twist
vec3 curve = bezier(p, controlPoints);
vec3 tangent = normalize(bezierTangent(p, controlPoints));
float twist = p * twistAmount + iTime;
vec3 normal = vec3(cos(twist), sin(twist), 0);
// Make normal perpendicular to tangent
normal = normalize(normal - dot(normal, tangent) * tangent);
vec3 binormal = cross(tangent, normal);
// Ribbon width
vec3 vertex = curve + normal * width * side;
